import Foundation
import Testing
@testable import DeeCore

// Golden tests for PromptBuilder against the REAL Qwen3.5 chat template.
//
// Fixtures: Tests/DeeCoreTests/Fixtures/prompt_goldens.json, generated by
// scripts/gen_prompt_goldens.py from docs/reference/qwen35_chat_template.jinja
// (the template embedded in Qwen3.5-4B-Q4_K_M.gguf), rendered with jinja2 configured
// like HF transformers. Regenerate with: python3 scripts/gen_prompt_goldens.py
//
// The package declares no resources, so the fixture is located via #filePath.

// MARK: - Fixture loading

struct Golden: Sendable, CustomTestStringConvertible {
    let name: String
    let messages: [ChatMessage]
    let tools: [ToolSpec]
    let toolTemplateJSON: [String]
    let enableThinking: Bool
    let addGenerationPrompt: Bool
    let expected: String

    var testDescription: String { name }

    static let fixtureURL: URL = URL(fileURLWithPath: #filePath)
        .deletingLastPathComponent()
        .appendingPathComponent("Fixtures/prompt_goldens.json")

    static let all: [Golden] = {
        do { return try load() } catch {
            Issue.record("Failed to load \(fixtureURL.path): \(error)")
            return []
        }
    }()

    enum FixtureError: Error { case malformed(String) }

    static func load() throws -> [Golden] {
        let data = try Data(contentsOf: fixtureURL)
        guard let root = try JSONSerialization.jsonObject(with: data) as? [[String: Any]] else {
            throw FixtureError.malformed("root is not an array of objects")
        }
        return try root.map(parseScenario)
    }

    static func parseScenario(_ s: [String: Any]) throws -> Golden {
        guard let name = s["name"] as? String,
              let rawMessages = s["messages"] as? [[String: Any]],
              let rawTools = s["tools"] as? [[String: Any]],
              let orders = s["tool_param_order"] as? [[String]],
              let toolJSON = s["tool_template_json"] as? [String],
              let thinking = s["enable_thinking"] as? Bool,
              let genPrompt = s["add_generation_prompt"] as? Bool,
              let expected = s["expected"] as? String
        else { throw FixtureError.malformed("scenario fields") }
        guard orders.count == rawTools.count else { throw FixtureError.malformed("\(name): tool_param_order count") }
        let tools = try zip(rawTools, orders).map { try parseTool($0.0, order: $0.1, scenario: name) }
        let messages = try rawMessages.map { try parseMessage($0, scenario: name) }
        return Golden(name: name, messages: messages, tools: tools, toolTemplateJSON: toolJSON,
                      enableThinking: thinking, addGenerationPrompt: genPrompt, expected: expected)
    }

    /// Maps the exact `ToolSpec.templateJSON` shape back to a `ToolSpec`.
    /// `order` restores property order (JSONSerialization dictionaries are unordered).
    static func parseTool(_ t: [String: Any], order: [String], scenario: String) throws -> ToolSpec {
        guard t["type"] as? String == "function",
              let fn = t["function"] as? [String: Any],
              let name = fn["name"] as? String,
              let description = fn["description"] as? String,
              let params = fn["parameters"] as? [String: Any],
              params["type"] as? String == "object",
              let props = params["properties"] as? [String: Any],
              let required = params["required"] as? [String]
        else { throw FixtureError.malformed("\(scenario): tool shape") }
        guard Set(order) == Set(props.keys), order.count == props.count else {
            throw FixtureError.malformed("\(scenario): param order mismatch for \(name)")
        }
        let parameters: [ToolParameter] = try order.map { pname in
            guard let p = props[pname] as? [String: Any],
                  let kindRaw = p["type"] as? String,
                  let kind = ToolParameter.Kind(rawValue: kindRaw),
                  let pdesc = p["description"] as? String
            else { throw FixtureError.malformed("\(scenario): param \(pname)") }
            return ToolParameter(pname, kind, pdesc, required: required.contains(pname), allowed: p["enum"] as? [String])
        }
        return ToolSpec(name: name, description: description, parameters: parameters)
    }

    static func parseMessage(_ m: [String: Any], scenario: String) throws -> ChatMessage {
        guard let roleRaw = m["role"] as? String, let role = Role(rawValue: roleRaw),
              let content = m["content"] as? String
        else { throw FixtureError.malformed("\(scenario): message") }
        let calls: [ToolCall] = try ((m["tool_calls"] as? [[String: Any]]) ?? []).map { c in
            guard let name = c["name"] as? String, let args = c["arguments"] as? [[String]] else {
                throw FixtureError.malformed("\(scenario): tool call")
            }
            return ToolCall(name: name, arguments: try args.map { pair in
                guard pair.count == 2 else { throw FixtureError.malformed("\(scenario): argument pair") }
                return ToolArgument(pair[0], pair[1])
            })
        }
        return ChatMessage(role: role, content: content, reasoning: m["reasoning_content"] as? String, toolCalls: calls)
    }
}

/// Byte-level comparison (Swift `==` uses canonical equivalence, which is too lenient
/// for prompt text) with a human-readable hint pointing at the first differing byte.
func byteDiff(_ actual: String, _ expected: String) -> String? {
    let a = Array(actual.utf8), e = Array(expected.utf8)
    if a == e { return nil }
    var i = 0
    while i < min(a.count, e.count), a[i] == e[i] { i += 1 }
    func window(_ bytes: [UInt8]) -> String {
        let lo = max(0, i - 40), hi = min(bytes.count, i + 40)
        let s = String(decoding: bytes[lo..<hi], as: UTF8.self)
        return s.debugDescription
    }
    return """
    first difference at byte \(i) (actual \(a.count) bytes, expected \(e.count) bytes)
      actual:   …\(window(a))…
      expected: …\(window(e))…
    """
}

// MARK: - Suite

@Suite struct PromptBuilderTests {

    /// Scenarios exposing a known source bug. PromptBuilder.trim uses
    /// `.whitespacesAndNewlines`, which does not include U+001C...U+001F; Python's
    /// `str.strip()` (Jinja `|trim`) strips them. (Fixed; kept as a hook for future gaps.)
    static let knownIssues: [String: String] = [:]

    /// Runs `body`, wrapping it in `withKnownIssue` if the scenario is a known bug.
    static func checking(_ name: String, _ body: () -> Void) {
        if let reason = knownIssues[name] {
            withKnownIssue(Comment(rawValue: reason)) { body() }
        } else {
            body()
        }
    }

    // MARK: Canonical goldens

    @Test func fixtureLoadsAllScenarios() throws {
        let goldens = try Golden.load()
        #expect(goldens.count >= 15)
        #expect(Set(goldens.map(\.name)).count == goldens.count, "scenario names must be unique")
    }

    @Test(arguments: Golden.all)
    func canonicalMatchesReferenceTemplate(_ g: Golden) {
        Self.checking(g.name) {
            let actual = PromptBuilder.render(
                g.messages, tools: g.tools,
                addGenerationPrompt: g.addGenerationPrompt,
                enableThinking: g.enableThinking,
                mode: .canonical)
            if let diff = byteDiff(actual, g.expected) {
                Issue.record("[\(g.name)] canonical render differs from reference template:\n\(diff)")
            }
        }
    }

    @Test(arguments: Golden.all)
    func toolSpecTemplateJSONMatchesPythonTojson(_ g: Golden) {
        #expect(g.tools.count == g.toolTemplateJSON.count)
        for (spec, expected) in zip(g.tools, g.toolTemplateJSON) {
            if let diff = byteDiff(spec.templateJSON, expected) {
                Issue.record("[\(g.name)] \(spec.name).templateJSON differs:\n\(diff)")
            }
        }
    }

    // MARK: Generation prefix

    @Test func generationPrefixMatchesTemplate() {
        #expect(PromptBuilder.generationPrefix(thinking: true) == "<think>\n")
        #expect(PromptBuilder.generationPrefix(thinking: false) == "<think>\n\n</think>\n\n")
        let off = PromptBuilder.render([.user("hi")], enableThinking: false)
        let on = PromptBuilder.render([.user("hi")], enableThinking: true)
        #expect(off.hasSuffix("<|im_start|>assistant\n<think>\n\n</think>\n\n"))
        #expect(on.hasSuffix("<|im_start|>assistant\n<think>\n"))
    }

    // MARK: Verbatim mode

    @Test func verbatimReplaysRawCompletionOfHistoryTurn() {
        let raw = "<think>\n  messy reasoning, kept as-is  \n</think>\n\nHello!  "
        var reply = ChatMessage.assistant("Hello!", reasoning: "messy reasoning, kept as-is")
        reply.rawCompletion = raw
        let msgs: [ChatMessage] = [.system("sys"), .user("hi"), reply, .user("again")]

        let verbatim = PromptBuilder.render(msgs, mode: .verbatim)
        #expect(verbatim.contains("<|im_start|>assistant\n" + raw + "<|im_end|>\n<|im_start|>user\nagain"))

        // Canonical ignores rawCompletion and drops history reasoning.
        let canonical = PromptBuilder.render(msgs, mode: .canonical)
        #expect(canonical.contains("<|im_start|>assistant\nHello!<|im_end|>\n"))
        #expect(!canonical.contains("messy reasoning"))
    }

    @Test func verbatimReplaysRawCompletionInCurrentTurnToo() {
        let raw = "<think>\n\n</think>\n\n<tool_call>\n<function=get_time>\n</function>\n</tool_call>"
        var call = ChatMessage.assistant("", toolCalls: [ToolCall(name: "get_time")])
        call.rawCompletion = raw
        let out = PromptBuilder.render([.user("time?"), call, .tool("10:00")], mode: .verbatim)
        #expect(out == "<|im_start|>user\ntime?<|im_end|>\n<|im_start|>assistant\n" + raw
                + "<|im_end|>\n<|im_start|>user\n<tool_response>\n10:00\n</tool_response><|im_end|>\n"
                + "<|im_start|>assistant\n<think>\n\n</think>\n\n")
    }

    @Test func verbatimHistoryWithoutRawGetsEmptyThinkBlock() {
        let msgs: [ChatMessage] = [.user("a"), .assistant("b", reasoning: "secret"), .user("c")]
        let out = PromptBuilder.render(msgs, mode: .verbatim)
        #expect(out.contains("<|im_start|>assistant\n<think>\n\n</think>\n\nb<|im_end|>\n"))
        #expect(!out.contains("secret"))
    }

    @Test func verbatimWithoutAssistantTurnsEqualsCanonical() throws {
        for g in Golden.all where !g.messages.contains(where: { $0.role == .assistant }) {
            let v = PromptBuilder.render(g.messages, tools: g.tools, addGenerationPrompt: g.addGenerationPrompt,
                                         enableThinking: g.enableThinking, mode: .verbatim)
            Self.checking(g.name) { #expect(byteDiff(v, g.expected) == nil, "[\(g.name)]") }
        }
    }

    /// For a non-thinking structured reply, the raw form (`prefix + canonical body`) and the
    /// structured verbatim fallback must coincide — so history recorded either way replays
    /// identically.
    @Test func structuredAndRawVerbatimAgreeForNonThinkingReplies() {
        let calls = [ToolCall(name: "get_weather", arguments: [ToolArgument("location", "Oslo")])]
        let structured = ChatMessage.assistant("Checking.", toolCalls: calls)
        var withRaw = structured
        withRaw.rawCompletion = PromptBuilder.generationPrefix(thinking: false)
            + "Checking.\n\n<tool_call>\n<function=get_weather>\n<parameter=location>\nOslo\n</parameter>\n</function>\n</tool_call>"
        let tail: [ChatMessage] = [.tool("rain"), .assistant("Rainy."), .user("thanks")]
        let a = PromptBuilder.render([.user("weather?"), structured] + tail, mode: .verbatim)
        let b = PromptBuilder.render([.user("weather?"), withRaw] + tail, mode: .verbatim)
        #expect(byteDiff(a, b) == nil)
    }

    // MARK: KEY INVARIANT — append-only prompts in verbatim mode

    /// Simulates a multi-turn conversation with a fake model. After each generation,
    /// the assistant message stores `rawCompletion = generationPrefix + generated`. The
    /// next prompt must start with (previous prompt + generated text), so the model's
    /// recurrent state never has to roll back.
    @Test func verbatimPromptIsAppendOnlyAcrossTurns() {
        let clock = ToolSpec(name: "get_time", description: "Returns the current local time.")
        let tools = [clock]
        var messages: [ChatMessage] = [.system("You are Dee.")]
        var checks = 0

        /// Renders the prompt, "generates" `text`, appends the reply, and asserts that the
        /// following prompt (built by `next`) extends prompt + text.
        func step(thinking: Bool, generated text: String, content: String, reasoning: String? = nil,
                  toolCalls: [ToolCall] = [], next: [ChatMessage], nextThinking: Bool,
                  sourceLocation: SourceLocation = #_sourceLocation) {
            let prompt = PromptBuilder.render(messages, tools: tools, enableThinking: thinking, mode: .verbatim)
            #expect(prompt.hasSuffix("<|im_start|>assistant\n" + PromptBuilder.generationPrefix(thinking: thinking)),
                    sourceLocation: sourceLocation)
            var reply = ChatMessage.assistant(content, reasoning: reasoning, toolCalls: toolCalls)
            reply.rawCompletion = PromptBuilder.generationPrefix(thinking: thinking) + text
            messages.append(reply)
            messages += next
            let nextPrompt = PromptBuilder.render(messages, tools: tools, enableThinking: nextThinking, mode: .verbatim)
            let expectedPrefix = prompt + text
            if !Array(nextPrompt.utf8).starts(with: Array(expectedPrefix.utf8)) {
                let hint = byteDiff(String(decoding: Array(nextPrompt.utf8).prefix(expectedPrefix.utf8.count), as: UTF8.self),
                                    expectedPrefix) ?? "(next prompt shorter than expected prefix)"
                Issue.record("prompt is not append-only:\n\(hint)", sourceLocation: sourceLocation)
            }
            // The suffix after the generated text must begin by closing the turn.
            #expect(nextPrompt.dropFirst(expectedPrefix.count).hasPrefix("<|im_end|>\n"), sourceLocation: sourceLocation)
            checks += 1
        }

        // Turn 1 — thinking off, plain reply.
        messages.append(.user("Hi Dee!"))
        step(thinking: false, generated: "Hi! *beep* Nice to meet you.", content: "Hi! *beep* Nice to meet you.",
             next: [.user("Think about it: why do cats purr?")], nextThinking: true)

        // Turn 2 — thinking on (user asked to think), reasoning + answer.
        step(thinking: true,
             generated: "Purring is a vibration of the laryngeal muscles...\n</think>\n\nCats purr when content, and to self-soothe.",
             content: "Cats purr when content, and to self-soothe.",
             reasoning: "Purring is a vibration of the laryngeal muscles...",
             next: [.user("What time is it?")], nextThinking: true)

        // Turn 3 — thinking still on for this conversation; tool-call step, then the
        // tool response, then the final answer, then another user turn.
        step(thinking: true,
             generated: "The user wants the time; call the clock.\n</think>\n\n<tool_call>\n<function=get_time>\n</function>\n</tool_call>",
             content: "", reasoning: "The user wants the time; call the clock.",
             toolCalls: [ToolCall(name: "get_time")],
             next: [.tool("09:41")], nextThinking: true)
        step(thinking: true,
             generated: "Clock says 09:41.\n</think>\n\nIt's 9:41 in the morning!",
             content: "It's 9:41 in the morning!", reasoning: "Clock says 09:41.",
             next: [.user("Thanks! Set a reminder too.")], nextThinking: true)

        // Turn 4 — tool call with visible content and two calls, two tool responses.
        step(thinking: true,
             generated: "Two tools.\n</think>\n\nOn it!\n\n<tool_call>\n<function=get_time>\n</function>\n</tool_call>\n<tool_call>\n<function=get_time>\n</function>\n</tool_call>",
             content: "On it!", reasoning: "Two tools.",
             toolCalls: [ToolCall(name: "get_time"), ToolCall(name: "get_time")],
             next: [.tool("09:41"), .tool("09:41")], nextThinking: true)
        step(thinking: true, generated: "\n</think>\n\nDone.", content: "Done.", reasoning: "",
             next: [.user("bye")], nextThinking: true)

        #expect(checks == 6)
    }

    /// Same invariant with thinking off for every turn, including tool steps.
    @Test func verbatimPromptIsAppendOnlyWithThinkingOff() {
        let tools = [ToolSpec(name: "get_time", description: "Time.")]
        var messages: [ChatMessage] = [.user("time?")]
        let turns: [(String, ChatMessage, [ChatMessage])] = [
            ("<tool_call>\n<function=get_time>\n</function>\n</tool_call>",
             .assistant("", toolCalls: [ToolCall(name: "get_time")]), [.tool("10:00")]),
            ("It's ten.", .assistant("It's ten."), [.user("and now?")]),
            ("Let me look.\n\n<tool_call>\n<function=get_time>\n</function>\n</tool_call>",
             .assistant("Let me look.", toolCalls: [ToolCall(name: "get_time")]), [.tool("10:01")]),
            ("10:01!", .assistant("10:01!"), [.user("thanks")]),
        ]
        for (text, reply, next) in turns {
            let prompt = PromptBuilder.render(messages, tools: tools, enableThinking: false, mode: .verbatim)
            var r = reply
            r.rawCompletion = PromptBuilder.generationPrefix(thinking: false) + text
            messages.append(r)
            messages += next
            let nextPrompt = PromptBuilder.render(messages, tools: tools, enableThinking: false, mode: .verbatim)
            #expect(Array(nextPrompt.utf8).starts(with: Array((prompt + text).utf8)), "after: \(text.debugDescription)")
        }
    }

    /// Documents WHY verbatim exists: canonical mode rewrites history (drops the think
    /// block), so it is NOT append-only once a turn moves into history.
    @Test func canonicalIsNotAppendOnlyAcrossTurns() {
        let first: [ChatMessage] = [.user("hi")]
        let prompt = PromptBuilder.render(first, enableThinking: false, mode: .canonical)
        let generated = "Hello!"
        var reply = ChatMessage.assistant(generated)
        reply.rawCompletion = PromptBuilder.generationPrefix(thinking: false) + generated
        let next = PromptBuilder.render(first + [reply, .user("again")], mode: .canonical)
        #expect(!next.hasPrefix(prompt + generated))
    }

    // MARK: Misc structural checks

    @Test func toolResponseFollowingAssistantOpensUserBlockOnce() {
        let out = PromptBuilder.render(
            [.user("q"), .assistant("", toolCalls: [ToolCall(name: "a"), ToolCall(name: "b")]), .tool("1"), .tool("2")],
            tools: [ToolSpec(name: "a", description: "A"), ToolSpec(name: "b", description: "B")])
        #expect(out.components(separatedBy: "<|im_start|>user").count - 1 == 2)
        #expect(out.contains("<|im_start|>user\n<tool_response>\n1\n</tool_response>\n<tool_response>\n2\n</tool_response><|im_end|>\n"))
    }
}
